(async () => {
  const pageIds = ['0:1', '1:2', '1:3', '1:4', '7:2'];
  const result = {};

  for (const pageId of pageIds) {
    const node = figma.getNodeById(pageId);
    if (!node) {
      result[pageId] = 'Not found';
      continue;
    }

    // Extract text contents recursively
    function extractText(n) {
      let texts = [];
      if (n.type === 'TEXT') {
        texts.push({ name: n.name, characters: n.characters, x: n.x, y: n.y });
      }
      if ('children' in n) {
        for (const child of n.children) {
          texts = texts.concat(extractText(child));
        }
      }
      return texts;
    }

    result[node.name] = {
      id: node.id,
      type: node.type,
      childrenCount: node.children ? node.children.length : 0,
      childrenNames: node.children ? node.children.map(c => ({ id: c.id, name: c.name, type: c.type })) : [],
      texts: extractText(node)
    };
  }

  return JSON.stringify(result, null, 2);
})();

