(async () => {
  const pageIds = ['1:2', '1:3', '1:4'];
  const info = {};

  for (const pageId of pageIds) {
    const page = figma.getNodeById(pageId);
    if (!page) continue;

    function inspectNode(n) {
      const obj = {
        id: n.id,
        name: n.name,
        type: n.type,
        x: n.x,
        y: n.y,
        width: n.width,
        height: n.height
      };
      if (n.type === 'TEXT') {
        obj.text = n.characters;
        obj.fontName = n.fontName;
        obj.fontSize = n.fontSize;
      }
      if (n.fills && Array.isArray(n.fills)) {
        obj.fills = n.fills.map(f => {
          if (f.type === 'IMAGE') return { type: 'IMAGE', imageHash: f.imageHash };
          if (f.type === 'SOLID') return { type: 'SOLID', color: f.color, opacity: f.opacity };
          return { type: f.type };
        });
      }
      if ('children' in n && n.children.length < 20) {
        obj.children = n.children.map(inspectNode);
      } else if ('children' in n) {
        obj.childrenCount = n.children.length;
        obj.childrenSample = n.children.slice(0, 10).map(c => ({ id: c.id, name: c.name, type: c.type }));
      }
      return obj;
    }

    info[page.name] = page.children.map(inspectNode);
  }

  return JSON.stringify(info, null, 2);
})();

