(async () => {
  function getSummary(node, depth = 0) {
    if (depth > 2) return { id: node.id, name: node.name, type: node.type };
    const res = { id: node.id, name: node.name, type: node.type };
    if (node.fills && node.fills.length > 0) {
      res.fills = node.fills.map(f => f.type === 'IMAGE' ? { type: 'IMAGE', imageHash: f.imageHash } : f);
    }
    if ('children' in node) {
      res.children = node.children.map(c => getSummary(c, depth + 1));
    }
    return res;
  }

  const mediaNode = figma.getNodeById('5:33'); // Media frame
  const compNode = figma.getNodeById('1:24'); // Components frame

  return JSON.stringify({
    media: getSummary(mediaNode),
    components: getSummary(compNode)
  }, null, 2);
})();

