(async () => {
  // Let's create the 5 frames in Workspace:
  // - 01_Onboarding
  // - 02_Home
  // - 03_Explore
  // - 04_Workout
  // - 05_Analytics
  //
  // Coordinates for placement:
  // 01_Onboarding: x=0, y=0
  // 02_Home: x=440, y=0
  // 03_Explore: x=880, y=0
  // 04_Workout: x=1320, y=0
  // 05_Analytics: x=1760, y=0
  // All frames are 390 x 844.

  const frameNames = ['01_Onboarding', '02_Home', '03_Explore', '04_Workout', '05_Analytics'];
  const frameWidth = 390;
  const frameHeight = 844;
  const createdFrames = {};

  const workspace = figma.getNodeById('7:2');

  // Clean up any existing frame on workspace
  for (const child of workspace.children) {
    child.remove();
  }

  for (let i = 0; i < frameNames.length; i++) {
    const name = frameNames[i];
    const f = figma.createFrame();
    f.name = name;
    f.resize(frameWidth, frameHeight);
    f.x = i * 440;
    f.y = 0;
    f.backgrounds = [{ type: 'SOLID', color: { r: 1, g: 1, b: 1 } }]; // white by default
    workspace.appendChild(f);
    createdFrames[name] = f.id;
  }

  return JSON.stringify(createdFrames);
})();

