(async () => {
  const workspace = figma.getNodeById('7:2');
  await figma.setCurrentPageAsync(workspace);

  // Frame IDs
  const f1 = figma.getNodeById('18:13'); // 01_Onboarding
  const f2 = figma.getNodeById('18:14'); // 02_Home
  const f3 = figma.getNodeById('18:15'); // 03_Explore
  const f4 = figma.getNodeById('18:16'); // 04_Workout
  const f5 = figma.getNodeById('18:17'); // 05_Analytics

  // Find clickable sub-elements
  function findNodeByName(parent, name) {
    if (parent.name === name) return parent;
    if ('children' in parent) {
      for (const child of parent.children) {
        const found = findNodeByName(child, name);
        if (found) return found;
      }
    }
    return null;
  }

  const getStartedBtn = findNodeByName(f1, "Get Started Button");
  const lowerCard = findNodeByName(f2, "Card_Lower_Body_Training");
  const tabHomeOn02 = findNodeByName(f2, "Tab_Home");
  const tabExploreOn02 = findNodeByName(f2, "Tab_Explore");
  const tabAnalyticsOn02 = findNodeByName(f2, "Tab_Analytics");

  const tabHomeOn03 = findNodeByName(f3, "Tab_Home");
  const tabExploreOn03 = findNodeByName(f3, "Tab_Explore");
  const tabAnalyticsOn03 = findNodeByName(f3, "Tab_Analytics");

  const backBtnOn04 = findNodeByName(f4, "Back_Button");

  const tabHomeOn05 = findNodeByName(f5, "Tab_Home");
  const tabExploreOn05 = findNodeByName(f5, "Tab_Explore");
  const tabAnalyticsOn05 = findNodeByName(f5, "Tab_Analytics");

  function setLink(sourceNode, targetFrame) {
    if (!sourceNode || !targetFrame) return false;
    sourceNode.reactions = [{
      action: {
        type: "NODE",
        destinationId: targetFrame.id,
        navigation: "NAVIGATE",
        transition: { type: "DISSOLVE", duration: 0.2, easing: { type: "EASE_IN_AND_OUT" } }
      },
      trigger: { type: "ON_CLICK" }
    }];
    return true;
  }

  const results = {
    onboardingToHome: setLink(getStartedBtn, f2),
    homeToWorkout: setLink(lowerCard, f4),
    homeToExplore: setLink(tabExploreOn02, f3),
    homeToAnalytics: setLink(tabAnalyticsOn02, f5),
    exploreToHome: setLink(tabHomeOn03, f2),
    exploreToAnalytics: setLink(tabAnalyticsOn03, f5),
    workoutToHome: setLink(backBtnOn04, f2),
    analyticsToHome: setLink(tabHomeOn05, f2),
    analyticsToExplore: setLink(tabExploreOn05, f3)
  };

  return JSON.stringify(results, null, 2);
})();

